dt-button.example:
new DataTable('#myTable', {
	layout: {
		topStart: {
			buttons: ['stateCreate', 'statesList']
		}
	},
	stateRestore: true
});

new DataTable('#example', {
	layout: {
		topStart: {
			buttons: [
				{
					extend: 'statesList',
					buttons: [
						'stateCreate',
						'statesRemoveAll',
						{extend: 'spacer', style: 'bar'}
					]
				}
			]
		}
	},
	stateRestore: true
});
